import { readFileSync } from 'node:fs';

import AxeBuilder from '@axe-core/playwright';
import { expect, test } from '@playwright/test';
import { seasonUploadPackageSchema } from '@sport-analytics/contracts';

const fixture = {
  fixtureId: '7',
  competitionId: '5',
  competitionName: 'Example Competition',
  seasonId: '15',
  season: '2026',
  seasonLabel: '2026',
  competitors: [
    { competitorId: '20', name: 'Wanderers' },
    { competitorId: '21', name: 'Strikers' },
  ],
  matchType: 'T20',
  teamType: 'international',
  gender: 'female',
  ballsPerOver: 6,
  scheduledOvers: 20,
  venue: null,
  toss: null,
  startDate: '2026-08-20',
  endDate: '2026-08-20',
};

const events = [
  {
    eventId: '123e4567-e89b-42d3-a456-426614174000',
    inningsId: '10',
    sequenceNumber: 1,
    overNumber: 0,
    positionInOver: 0,
    ballNumber: '0.1',
    strikerId: '20',
    nonStrikerId: '21',
    bowlerId: '22',
    runs: { offBat: 4, extras: 0, total: 4, nonBoundary: false },
    extras: {},
    wickets: [],
  },
];

const batchReference = '123e4567-e89b-42d3-a456-426614174000';

/**
 * The downloadable JSON template completed with readable names for the listed
 * fixture only, as the guided page asks (#500). Every placeholder must exist, so
 * a template change cannot quietly make the journey vacuous.
 */
function readableFixturePackage(): string {
  let text = readFileSync('apps/frontend/public/season-upload-template.json', 'utf8');
  const readableValues: [placeholder: string, value: string][] = [
    ['"Competition name"', `"${fixture.competitionName}"`],
    ['"2026-03-14"', `"${fixture.startDate}"`],
    ['"Home team"', '"Wanderers"'],
    ['"Away team"', '"Strikers"'],
  ];
  for (const [placeholder, value] of readableValues) {
    expect(text).toContain(placeholder);
    text = text.replaceAll(placeholder, value);
  }
  return text;
}

test.beforeEach(async ({ page }) => {
  await page.addInitScript(() => {
    const now = Math.floor(Date.now() / 1_000);
    window.localStorage.setItem(
      'sb-e2e-auth-token',
      JSON.stringify({
        access_token: 'approved-e2e-token',
        refresh_token: 'managed-by-supabase',
        expires_in: 3_600,
        expires_at: now + 3_600,
        token_type: 'bearer',
        user: {
          id: 'approved-user',
          aud: 'authenticated',
          role: 'authenticated',
          email: 'submitter@example.com',
          app_metadata: {},
          user_metadata: {},
          identities: [],
          created_at: '2026-08-16T00:00:00.000Z',
        },
      }),
    );
  });

  await page.route('**/api/v1/auth/me', async (route) => {
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify({
        user: {
          id: '17',
          subject: 'approved-user',
          displayName: 'Submitter User',
          role: 'submitter',
          approvalState: 'approved',
          requestedCompetition: { competitionId: '5', name: 'Premier T20' },
          competitionIds: ['5'],
        },
      }),
    });
  });

  await page.route('**/api/v1/competitions?*', async (route) => {
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify({
        data: [
          { competitionId: '5', name: 'Premier T20' },
          { competitionId: '8', name: 'University League' },
        ],
        pagination: { nextCursor: null },
      }),
    });
  });

  await page.route('**/api/v1/competitions/5', async (route) => {
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify({ data: { competitionId: '5', name: 'Example Competition' } }),
    });
  });

  await page.route('**/api/v1/fixtures?**', async (route) => {
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify({ data: [fixture], pagination: { nextCursor: null, totalPages: 1 } }),
    });
  });
});

test('Manage Submission opens the unified submission workflow', async ({ page }) => {
  await page.goto('/account/overview');
  await page.getByRole('button', { name: 'Manage Submission' }).click();
  await page.getByRole('link', { name: 'Submit data' }).click();

  await expect(page).toHaveURL(/\/submissions\/new$/);
  await expect(page.getByRole('heading', { name: 'Submit data' })).toBeVisible();
  await expect(page.getByRole('radio', { name: /Single fixture/ })).toBeChecked();
  await expect(page.getByRole('radio', { name: /Season/ })).toBeVisible();
  await expect(page.getByRole('radio', { name: /Back catalogue/ })).toBeVisible();
  await expect(page.getByRole('radio', { name: /Advanced technical JSON/ })).toBeVisible();
  await expect(page.getByRole('link', { name: 'Upload a batch' })).toHaveCount(0);

  // #500: the guided scopes and the identifier-based mode are separate groups,
  // and the default guided path shows no JSON editor.
  const guided = page.getByRole('group', { name: /Guided upload/ });
  const advanced = page.getByRole('group', { name: /application identifiers required/ });
  await expect(guided.getByRole('radio')).toHaveCount(3);
  await expect(guided.getByRole('radio', { name: /Advanced technical JSON/ })).toHaveCount(0);
  await expect(advanced.getByRole('radio', { name: /Advanced technical JSON/ })).toBeVisible();
  await expect(page.getByLabel('Delivery events JSON')).toHaveCount(0);
});

test('submitter originates a new fixture proposal for reviewer resolution', async ({ page }) => {
  await page.route('**/api/v1/batches', async (route) => {
    const request = route.request();
    expect(request.method()).toBe('POST');
    expect(request.headers()['x-batch-package-version']).toBe('1.1');
    expect(request.headers()['x-competition-id']).toBe('5');
    expect(request.postDataJSON()).toMatchObject({
      contractVersion: '1.1',
      competition: { context: { name: 'Example Competition' } },
      season: { context: { name: '2026' } },
      fixtures: [
        {
          sourceId: expect.stringMatching(/^submitter:fixture:/),
          context: {
            date: fixture.startDate,
            teams: [{ context: { name: 'Wanderers' } }, { context: { name: 'Strikers' } }],
          },
          proposal: {
            endDate: fixture.startDate,
            matchType: 'T20',
            teamType: 'club',
            gender: 'female',
            ballsPerOver: 6,
            outcome: 'no result',
            sourceVersion: '1',
            sourceRevision: 0,
          },
        },
      ],
    });
    expect(seasonUploadPackageSchema.safeParse(request.postDataJSON()).success).toBe(true);
    await route.fulfill({
      status: 202,
      contentType: 'application/json',
      body: JSON.stringify({
        data: {
          batchReference,
          status: 'stored',
          statusUrl: `/api/v1/batches/${batchReference}`,
          receivedAt: '2026-09-15T09:30:00.000Z',
        },
      }),
    });
  });

  await page.goto('/submissions/new');
  await page.getByLabel('Fixture', { exact: true }).selectOption('new');
  await expect(page.getByRole('group', { name: 'New fixture metadata' })).toBeVisible();
  await page.getByLabel('Season name').fill('2026');
  await page.getByLabel('Fixture date').fill(fixture.startDate);
  await page.getByLabel('Home team name').fill('Wanderers');
  await page.getByLabel('Away team name').fill('Strikers');
  await expect(page.getByLabel('Match type')).toHaveValue('T20');
  await page.getByLabel('Team type').selectOption('club');
  await page.getByLabel('Gender').selectOption('female');
  await page.getByLabel('Fixture package').setInputFiles({
    name: 'new-fixture.json',
    mimeType: 'application/json',
    buffer: Buffer.from(readableFixturePackage()),
  });
  await page.getByRole('button', { name: 'Upload fixture package' }).click();

  await expect(page.getByRole('heading', { name: 'Fixture upload received' })).toBeFocused();
  await expect(page.getByText(batchReference, { exact: true })).toBeVisible();
  await expect(page.getByText(/administrator can create the canonical fixture/i)).toBeVisible();
});

test('submitter stages advanced technical JSON with a keyboard', async ({ page }) => {
  await page.route('**/api/v1/batches', async (route) => {
    const request = route.request();
    expect(request.method()).toBe('POST');
    expect(request.headers()['x-competition-id']).toBe('5');
    expect(request.headers()['x-file-name']).toBe('technical-7.json');
    expect(request.postDataJSON()).toMatchObject({
      contractVersion: '1.0',
      fixtures: [
        {
          sourceId: 'app:fixture:7',
          innings: [
            {
              sourceId: 'app:innings:10',
              events: [
                {
                  eventId: `app:delivery:${events[0]!.eventId}`,
                  striker: { sourceId: 'app:participant:20' },
                  nonStriker: { sourceId: 'app:participant:21' },
                  bowler: { sourceId: 'app:participant:22' },
                },
              ],
            },
          ],
        },
      ],
    });

    await route.fulfill({
      status: 202,
      contentType: 'application/json',
      body: JSON.stringify({
        data: {
          batchReference,
          status: 'stored',
          statusUrl: `/api/v1/batches/${batchReference}`,
          receivedAt: '2026-08-16T09:30:00.000Z',
        },
      }),
    });
  });

  await page.goto('/submissions/new');
  await page.getByRole('radio', { name: /Advanced technical JSON/ }).click();

  const fixtureSelector = page.getByLabel('Fixture', { exact: true });
  const editor = page.getByLabel('Delivery events JSON');
  const submitButton = page.getByRole('button', { name: 'Submit events' });

  await expect(fixtureSelector).toHaveValue('7');
  await editor.fill(JSON.stringify(events, null, 2));

  await fixtureSelector.focus();
  await page.keyboard.press('Tab');
  await expect(editor).toBeFocused();
  await page.keyboard.press('Tab');
  await expect(submitButton).toBeFocused();
  await page.keyboard.press('Enter');

  const stagedHeading = page.locator(
    'h1:focus, h2:focus, h3:focus, h4:focus, h5:focus, h6:focus, [role="heading"]:focus',
  );
  await expect(stagedHeading).toBeFocused();
  await expect(page.getByText(batchReference, { exact: true })).toBeVisible();
  await expect(page.locator(`a[href="/submissions/batches/${batchReference}"]`)).toHaveAttribute(
    'href',
    `/submissions/batches/${batchReference}`,
  );
  await expect(page.getByRole('button', { name: 'Save correction' })).toHaveCount(0);

  const hasHorizontalOverflow = await page.evaluate(
    () => document.documentElement.scrollWidth > document.documentElement.clientWidth,
  );
  expect(hasHorizontalOverflow).toBe(false);

  const results = await new AxeBuilder({ page }).analyze();
  const seriousOrCriticalViolations = results.violations.filter(
    (violation) => violation.impact === 'serious' || violation.impact === 'critical',
  );
  expect(seriousOrCriticalViolations).toEqual([]);
});

test('technical JSON schema errors remain associated with the editor and receive focus', async ({
  page,
}) => {
  const invalidEvents = events.map((event) => ({
    ...event,
    runs: { ...event.runs, total: event.runs.total + 1 },
  }));

  await page.goto('/submissions/new');
  await page.getByRole('radio', { name: /Advanced technical JSON/ }).click();
  const editor = page.getByLabel('Delivery events JSON');
  await editor.fill(JSON.stringify(invalidEvents));
  await page.getByRole('button', { name: 'Submit events' }).click();

  await expect(page.getByRole('heading', { name: 'Submission rejected' })).toBeFocused();
  await expect(page.getByText('Total runs must equal off-bat runs plus extras.')).toBeVisible();
  await expect(editor).toHaveAttribute('aria-invalid', 'true');
  await expect(editor).toHaveAttribute('aria-describedby', /submission-validation-results/);
});

